/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// Populates the METInventLocationIdToTmp temp table with InventLocationId,
/// Name, and InventSiteId values from the InventLocation table. The data is
/// stored temporarily in memory and used for lookup or processing within
/// the current session.
/// </summary>
public METInventLocationIdToTmp populateInventLocationTemp(METInventLocationIdToTmp tempBuffer)
{
    Unchecked(Uncheck::XDS)
    {
        InventLocation inventLocation;

        while select InventLocationId, Name, InventSiteId
            from inventLocation
        {
            tempBuffer.clear();
            tempBuffer.InventLocationId = inventLocation.InventLocationId;
            tempBuffer.Name             = inventLocation.Name;
            tempBuffer.InventSiteId     = inventLocation.InventSiteId;

            tempBuffer.insert();
        }

    }

    return tempBuffer;
}

/// <summary>
/// Builds and displays a lookup for the METInventLocationIdToTmp InMemory temp table.
/// Supports dynamic filtering based on the user's typed text.
///
/// This lookup:
///  - Uses SysTableLookup with an InMemory temp table buffer
///  - Applies a wildcard filter (*text*) on InventLocationId when text is entered
///  - Clears ranges after lookup is rendered to avoid stale filters
///  - Displays multiple fields (Location, Name, Site)
///
/// Notes for InMemory temp tables:
///  - InMemory tables exist only in AOS memory and are tied to the current buffer instance
///  - parmTmpBuffer(this) is required so SysTableLookup uses the correct in-memory dataset
///  - Lookup filtering is applied only when the lookup is opened (ComboBox behavior)
///  - textChange() does NOT refresh the lookup for ComboBox controls
///
/// This method is optimized for InMemory temp tables and avoids unsupported ComboBox refresh calls.
/// </summary>
/// <param name="_control">
/// The FormStringControl instance that triggered the lookup.
/// The control's current text is used to build the dynamic filter.
/// </param>
/// <remarks>
/// InMemory temp tables differ from TempDB tables in storage, but the lookup pattern is identical:
///     - Always bind the lookup to the current buffer using parmTmpBuffer(this)
///     - Always clear ranges after performFormLookup() to prevent stale filters
/// </remarks>
public void lookup(FormStringControl _control)
{
    SysTableLookup          sysTableLookup;
    Query                   query = new Query();
    QueryBuildDataSource    qbds;
    QueryBuildRange         qbr;
    str                     searchText = _control.valueStr();

    sysTableLookup = SysTableLookup::newParameters(
    tableNum(METInventLocationIdToTmp),
    _control);

    qbds = query.addDataSource(tableNum(METInventLocationIdToTmp));

    // Apply dynamic filter for first-time lookup
    if (searchText)
    {
        qbr = qbds.addRange(fieldNum(METInventLocationIdToTmp, InventLocationId));
        qbr.value(strFmt('%1*', searchText));
    }

    sysTableLookup.addLookupfield(fieldNum(METInventLocationIdToTmp, InventLocationId));
    sysTableLookup.addLookupfield(fieldNum(METInventLocationIdToTmp, Name));
    sysTableLookup.addLookupfield(fieldNum(METInventLocationIdToTmp, InventSiteId));

    sysTableLookup.parmTmpBuffer(this);
    sysTableLookup.parmQuery(query);

    sysTableLookup.performFormLookup();

    qbds.clearRanges();
}
